(51, 'BV-150425-62509190', '32df3e3 3442 3423444234234234324234', '32df3e3-3442-3423444234234234324234', '<p><img src=\"http://127.0.0.1:8000/storage/uploads/TE5kceHJ83n1Ybna94H145AdRhK1YRFEwMDZNXgK.png\" width=\"150\" height=\"150\" data-moderated=\"true\" data-no-remoderation=\"true\"><p><img class=\"\" style=\"display: inline;\" src=\"http://127.0.0.1:8000/storage/uploads/url_1744703915_c77d72bdd4.jpg\" alt=\"Tinh th&#7847;n &#273;&#7893;i m&#7899;i v&agrave; s&aacute;ng t&#7841;o qua thi&#7871;t k&#7871; &#273;&#7891;ng h&#7891; Philippe Auguste - 1\" data-need-moderation=\"true\" data-paste-id=\"img-1744703902863-2986\" data-moderated=\"true\" data-no-remoderation=\"true\"></p><p>&nbsp;</p><p>dfasdf</p><p>&nbsp;</p></p>\n', NULL, 0, 4, 2, 4, 'thumbnails/FUqMiWLzD5WCx3tXWYxLolBCqF1VCAF9xCfu4Xxm.png', 'pending', 6, NULL, '2025-04-15 07:59:11', '2025-04-23 12:13:15'),
