(53, 'BV-150425-26103701', 'ssdsds423', 'ssdsds423', '<p>tttt</p>', NULL, 0, 4, 3, NULL, 'thumbnails/maO1pqPzuNhOujRpplplnOqp3Lkl8wF279MeYBSh.png', 'pending', 6, NULL, '2025-04-15 09:03:43', '2025-04-23 12:13:15'),
(55, 'BV-190425-78120815', 'Phú Yên đề xuất hỗ trợ đi lại, chỗ ở cho 1.300 cán bộ sau sáp nhập tỉnh', 'phu-yen-de-xuat-ho-tro-di-lai-cho-o-cho-1300-can-bo-sau-sap-nhap-tinh', '<p class=\"description\" style=\"margin: 0px 0px 15px; padding: 0px; box-sizing: border-box; text-rendering: optimizelegibility; font-size: 18px; line-height: 28.8px; font-weight: 400; color: #222222; font-family: arial; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Sở T&agrave;i ch&iacute;nh tỉnh đề xuất hỗ trợ chi ph&iacute; đi lại, chỗ ở cho 1.300 c&aacute;n bộ phải đi l&agrave;m tại tỉnh Đăk Lăk từ 1,6 đến tr&ecirc;n 3 triệu đồng mỗi th&aacute;ng</p>\r\n<article class=\"fck_detail \" style=\"margin: 0px; padding: 0px; box-sizing: border-box; text-rendering: optimizelegibility; width: 680px; float: left; position: relative; font: 400 18px / 28.8px arial; color: #222222; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">\r\n<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px;\">Theo Sở T&agrave;i ch&iacute;nh, dự kiến tổng số c&aacute;n bộ, c&ocirc;ng chức, vi&ecirc;n chức khi s&aacute;p nhập tỉnh c&oacute; nhu cầu đi từ TP Tuy H&ograve;a (Ph&uacute; Y&ecirc;n) đến TP Bu&ocirc;n Ma Thuột (Đăk Lăk) v&agrave; ngược lại l&agrave; khoảng 1.300 người (kh&ocirc;ng bao gồm c&aacute;c đơn vị lực lượng vũ trang).</p>\r\n<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px;\">Tuy nhi&ecirc;n, xe c&ocirc;ng vụ của tỉnh Ph&uacute; Y&ecirc;n kh&ocirc;ng đủ phục vụ số lượng tr&ecirc;n. Sở T&agrave;i ch&iacute;nh dự kiến chi ph&iacute; đi lại sau s&aacute;p nhập tỉnh l&agrave; 1,6 triệu đồng mỗi người/th&aacute;ng. Trường hợp kh&ocirc;ng sử dụng xe chung do tỉnh bố tr&iacute; th&igrave; hỗ trợ bằng tiền mặt.</p>\r\n<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px;\">Ngo&agrave;i ra, c&aacute;n bộ, c&ocirc;ng chức, vi&ecirc;n chức kh&ocirc;ng được bố tr&iacute; nh&agrave; ở c&ocirc;ng vụ sẽ được nhận chi ph&iacute; hỗ trợ chỗ ở l&agrave; 3 triệu đồng mỗi người/th&aacute;ng.</p>\r\n</article>', NULL, 0, 4, 3, NULL, 'thumbnails/pebeyBUBvGNMkNAdhsoC7oT2EyLWhGRVXlcNpexT.png', 'pending', 1, NULL, '2025-04-19 01:53:15', '2025-04-23 12:13:15'),
(56, 'BV-190425-90804334', 'c tại Đăk Lăk lựa ch', 'c-tai-dak-lak-lua-ch', '<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Sở T&agrave;i ch&iacute;nh cho biết Trung ương chưa quy định nội dung, ch&iacute;nh s&aacute;ch, mức hỗ trợ cho c&aacute;n bộ, c&ocirc;ng chức, vi&ecirc;n chức khi sắp xếp, s&aacute;p nhập. Dựa v&agrave;o nhu cầu thực tế, sở đề xuất chủ trương hỗ trợ chi ph&iacute; sinh hoạt cho c&aacute;c c&aacute;n bộ tỉnh Ph&uacute; Y&ecirc;n l&agrave;m việc tại Đăk Lăk lựa chọn một trong hai phương &aacute;n.</p>', NULL, 0, 4, 2, NULL, 'thumbnails/JnvF2Yk2Taxzm1RibuHOPpWRtL0rgVvt3V7QUDqW.png', 'pending', 1, NULL, '2025-04-19 02:27:17', '2025-04-23 12:13:15'),
(57, 'BV-190425-22949968', 'ông Cầu và Đông Hòa, c', 'ong-cau-va-dong-hoa-c', '<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Tỉnh Ph&uacute; Y&ecirc;n diện t&iacute;ch hơn 5.000 km2, d&acirc;n số hơn một triệu người, gồm 9 đơn vị h&agrave;nh ch&iacute;nh cấp huyện l&agrave; th&agrave;nh phố Tuy H&ograve;a, hai thị x&atilde; S&ocirc;ng Cầu v&agrave; Đ&ocirc;ng H&ograve;a, c&aacute;c huyện Tuy An, Ph&uacute; H&ograve;a, T&acirc;y H&ograve;a, Sơn H&ograve;a, S&ocirc;ng Hinh.</p>', NULL, 0, 4, 2, NULL, 'thumbnails/MDFJWwpctzWvEk1PP5IEvZLnZAjJOtbeihV68f5Z.png', 'rejected', 1, 2, '2025-04-19 02:41:04', '2025-04-25 02:17:11'),
(58, 'BV-190425-11037857', 'Phương án sắp xếp của 7 quận ở Hà Nội', 'phuong-an-sap-xep-cua-7-quan-o-ha-noi', 'https://cdnphoto.dantri.com.vn/0euCKcn_zqUSqP4ZsNMLJ3ckzFw=/thumb_w/1020/2024/11/22/putinreuters-1732274504328.jpg\" alt=\"Ông Putin cảnh báo đanh thép Ukraine sau lệnh ngừng bắn - 1\" data-width=\"5841\" data-height=\"3825\" data-original=\"https://cdnphoto.dantri.com.vn/lRuummeDZ4GoOzRj7p5Sof-SBS4=/2024/11/22/putinreuters-1732274504328.jpg\" data-photo-id=\"3228998\" data-track-content=\"\" data-content-name=\"article-content-image\" data-content-piece=\"article-content-image_3228998\" data-content-target=\"/the-gioi/ong-putin-canh-bao-danh-thep-ukraine-sau-lenh-ngung-ban-20250422053321637.htm\" data-src=\"https://cdnphoto.dantri.com.vn/0euCKcn_zqUSqP4ZsNMLJ3ckzFw=/thumb_w/1020/2024/11/22/putinreuters-1732274504328.jpg\" data-srcset=\"https://cdnphoto.dantri.com.vn/0euCKcn_zqUSqP4ZsNMLJ3ckzFw=/thumb_w/1020/2024/11/22/putinreuters-1732274504328.jpg 1x, https://cdnphoto.dantri.com.vn/rvLtd7LTwmOlDDXHcaNv-P_f3ps=/thumb_w/1360/2024/11/22/putinreuters-1732274504328.jpg 2x\" data-ll-status=\"loaded\" class=\"entered loaded\" srcset=\"https://cdnphoto.dantri.com.vn/0euCKcn_zqUSqP4ZsNMLJ3ckzFw=/thumb_w/1020/2024/11/22/putinreuters-1732274504328.jpg 1x, https://cdnphoto.dantri.com.vn/rvLtd7LTwmOlDDXHcaNv-P_f3ps=/thumb_w/1360/2024/11/22/putinreuters-1732274504328.jpg 2x\" data-adbro-processed=\"true\"><figcaption><p>Tổng thống Vladimir Putin (Ảnh: Reuters).</p></figcaption></figure><div id=\"dta-100000-container\" class=\"dta-unit\" style=\"border-bottom: 0px; width: auto !important;\"></div><p>\"Lập trường của chúng tôi đối với lệnh ngừng bắn là tích cực và đó là lý do chúng tôi đề xuất sáng kiến này, đặc biệt là trong những ngày lễ Phục sinh linh thiêng\", Tổng thống Vladimir Putin tuyên bố hôm 21/4.</p><p>Trước đó, Tổng thống Putin ngày 19/4 đã tuyên bố lệnh ngừng bắn đơn phương kéo dài 30 giờ, tạm dừng các hoạt động giao tranh với Ukraine.</p><p>Bình luận về lệnh ngừng bắn, nhà lãnh đạo Nga cho biết điều này chứng tỏ rằng không giống như Kiev, Moscow đang tìm kiếm một giải pháp hòa bình cho cuộc xung đột.</p><p>\"Chúng tôi đã thấy phản ứng ban đầu từ Kiev, tôi tin rằng mọi người đều đã thấy. Họ tuyên bố đề xuất của chúng tôi là \"đùa giỡn với mạng sống\"…\", ông Putin nói thêm, đề cập đến tuyên bố của Tổng thống Ukraine Volodymyr Zelensky.</p><p>Ông Zelensky cho rằng sáng kiến ngừng bắn của Nga không chân thành.</p><p>Theo Tổng thống Putin, Ukraine muốn kéo dài lệnh ngừng bắn sau thời hạn 30 giờ. Nhà lãnh đạo Nga trích dẫn các báo cáo <a href=\"https://dantri.com.vn/the-gioi/quan-su.htm\" data-auto-link-id=\"6137992efb044100119a147e\" data-track-content=\"\" data-content-name=\"article-content-autolink\" data-content-piece=\"article-content-autolink_6137992efb044100119a147e\" data-content-target=\"/the-gioi/ong-putin-canh-bao-danh-thep-ukraine-sau-lenh-ngung-ban-20250422053321637.htm\">quân sự</a> cho biết các hoạt động giao tranh đã giảm bớt, nhưng không phải chấm dứt hoàn toàn.</p><p>Tổng thống Putin cũng đưa ra cảnh báo cứng rắn sau các cáo buộc gần đây của Ukraine về các cuộc tấn công tầm xa của Nga vào các khu vực mà Kiev cho là địa điểm dân sự.</p><p>Ông Putin nhấn mạnh rằng trong tất cả các trường hợp như vậy, chính quyền Ukraine đã sử dụng các địa điểm dân sự cho mục đích quân sự và Nga có quyền hành động.</p><p>\"Mọi người đều biết cuộc tấn công mà lực lượng vũ trang của chúng tôi thực hiện vào một trung tâm hội nghị của một trường đại học ở Sumy. Đó có phải là một địa điểm dân sự không? Chắc chắn rồi. Nhưng nó được sử dụng để trao thưởng cho những binh lính đã phạm tội ở vùng Kursk của Nga\", ông Putin nói thêm.</p><p>\"Chúng tôi coi những người đó là tội phạm và phải chịu trách nhiệm về những gì họ đã làm. Đây là hành động trừng phạt họ\", ông Putin nhấn mạnh.</p><p>Ông Putin cũng xác nhận Moscow đã thực hiện một cuộc tấn công khác vào một cơ sở nông nghiệp ở vùng Odessa của Ukraine, nơi Kiev và lực lượng nước ngoài đang tiến hành một hoạt động thử nghiệm vũ khí.</p><p>Nga thường coi các cuộc tập trung của quân nhân Ukraine là mục tiêu quân sự, ngay cả khi các sự kiện này diễn ra bên trong một tòa nhà dân sự.</p><p>Ông Putin tuyên bố Nga nhắm mục tiêu vào quân nhân Ukraine và nước ngoài, bất kể họ có đóng quân tại các cơ sở dân sự hay không.</p><p>Bộ Quốc phòng Nga báo cáo vào ngày 21/4 rằng họ đã ghi nhận 4.900 vụ vi phạm lệnh ngừng bắn của quân đội Ukraine.</p><p>Theo Bộ Quốc phòng Nga, chính quyền Kiev tiếp tục tấn công vào các vị trí của quân đội Nga và các cơ sở dân sự tại các khu vực biên giới ở Belgorod, Bryansk và Kursk cũng như tại bán đảo Crimea. Quân đội Ukraine cũng đã thực hiện các cuộc tấn công bằng 90 máy bay không người lái.</p>', NULL, 0, 4, 2, NULL, 'thumbnails/IgMRTGkaSqiBc0gHE7cwH7g4MFPdGWHsxlRb70xM.png', 'published', 2, 1, '2025-04-19 02:52:21', '2025-04-28 13:57:28'),
(59, 'BV-190425-22461132', 'Phương án sáp nhập cấp xã của Huế, Hòa Bình, Vĩnh Phúc, Bắc Kạn', 'phuong-an-sap-nhap-cap-xa-cua-hue-hoa-binh-vinh-phuc-bac-kan', '<h1 class=\"title-detail\" style=\"margin: 0px 0px 15px; padding: 0px; box-sizing: border-box; text-rendering: optimizelegibility; font: 700 36px / 1.6 Merriweather, serif; color: #222222; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Phương &aacute;n s&aacute;p nhập cấp x&atilde; của Huế, H&ograve;a B&igrave;nh, Vĩnh Ph&uacute;c, Bắc Kạn</h1>', NULL, 0, 4, 3, NULL, 'thumbnails/n93nMXrphxvK2nT9VMGgYBkZEMTztw3rSxJuZGzi.jpg', 'published', 1, 1, '2025-04-19 02:54:13', '2025-04-23 12:13:15'),
(60, 'BV-190425-86850121', 'ơng Vinh và xã Quảng Thành, đổi tên th', 'ong-vinh-va-xa-quang-thanh-doi-ten-th', '<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Trong đ&oacute;, phường Thuận An sẽ mở rộng bằng việc s&aacute;p nhập hai x&atilde; của huyện Ph&uacute; Vang; phường Hương Phong sẽ c&oacute; th&ecirc;m phường Hương Vinh v&agrave; x&atilde; Quảng Th&agrave;nh, đổi t&ecirc;n th&agrave;nh phường H&oacute;a Ch&acirc;u. 6 phường trung t&acirc;m của quận Thuận H&oacute;a sẽ hợp nhất th&agrave;nh phường Thuận H&oacute;a; v&agrave; phường Ph&uacute; Thượng dự kiến sẽ s&aacute;p nhập th&ecirc;m hai x&atilde; l&acirc;n cận từ huyện Ph&uacute; Vang.</p>\r\n<figure class=\"tplCaption action_thumb_added\" style=\"margin: 0px auto 15px; padding: 0px; box-sizing: border-box; text-rendering: optimizelegibility; max-width: 100%; clear: both; position: relative; text-align: center; width: 680px; float: left; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\" itemprop=\"associatedMedia image\" itemscope=\"\" itemtype=\"http://schema.org/ImageObject\" data-size=\"true\">\r\n<div class=\"fig-picture el_valid\" sty