(62, 'BV-190425-01302949', 'TP Đà Nẵng mới dự kiến có 107 xã phường và đặc', 'tp-da-nang-moi-du-kien-co-107-xa-phuong-va-dac', '<h1 class=\"title-detail\" style=\"margin: 0px 0px 15px; padding: 0px; box-sizing: border-box; text-rendering: optimizelegibility; font: 700 36px / 1.6 Merriweather, serif; color: #222222; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">TP Đ&agrave; Nẵng mới dự kiến c&oacute; 107 x&atilde; phường v&agrave; đặc khu</h1>', NULL, 0, 4, 2, NULL, 'thumbnails/vLsDNeA5eIHnXkuy5CN7AUrsEFJ3xDmxy0v3S2Rd.png', 'published', 2, 2, '2025-04-19 03:09:50', '2025-04-26 14:51:20'),
(63, 'BV-190425-11496267', 'Nam. Ảnh: Đắc Thành', 'nam-anh-dac-thanh', '<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Theo phương &aacute;n, c&aacute;c đơn vị đặc th&ugrave; được giữ nguy&ecirc;n l&agrave; Ban Quản l&yacute; Khu c&ocirc;ng nghệ cao v&agrave; c&aacute;c khu c&ocirc;ng nghiệp; Ban Quản l&yacute; c&aacute;c khu kinh tế.</p>\r\n<figure class=\"tplCaption action_thumb_added\" style=\"margin: 0px auto 15px; padding: 0px; box-sizing: border-box; text-rendering: optimizelegibility; max-width: 100%; clear: both; position: relative; text-align: center; width: 680px; float: left; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\" itemprop=\"associatedMedia image\" itemscope=\"\" itemtype=\"http://schema.org/ImageObject\" data-size=\"true\">\r\n<div class=\"fig-picture el_valid\" style=\"margin: 0px; padding: 0px 0px 399.328px; box-sizing: border-box; text-rendering: optimizelegibility; width: 680px; float: left; display: table; -webkit-box-pack: center; justify-content: center; text-align: center; position: relative;\" data-src=\"https://i1-vnexpress.vnecdn.net/2025/04/18/DJI-0837-1744981387-89