(64, 'BV-190425-46077815', 'hợp nhất, tương t', 'hop-nhat-tuong-t', '<p><span style=\"color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; float: none; display: inline !important;\">iến thiết hai địa phương sẽ được hợp nhất, tương tự C&ocirc;ng ty TNHH MTV Khai th&aacute;c thủy lợi c</span></p>', NULL, 0, 4, 3, NULL, 'thumbnails/segXjwOnMjf9k8WHUyjtxZN74vOeBOJVE3apXXp2.png', 'pending', 1, NULL, '2025-04-19 07:49:31', '2025-04-23 12:13:15'),
(65, 'BV-190425-37841245', 'nước giao nhiệm vụ trướ', 'nuoc-giao-nhiem-vu-truo', '<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Theo phương &aacute;n, Ủy ban Mặt trận Tổ quốc Việt Nam TP Đ&agrave; Nẵng v&agrave; Quảng Nam được hợp nhất, gồm 9 đầu mối. 48 tổ chức hội quần ch&uacute;ng do Đảng, Nh&agrave; nước giao nhiệm vụ trước mắt được giữ nguy&ecirc;n, sau đ&oacute; từng bước sắp xếp theo đề &aacute;n của Trung ương.</p>', NULL, 0, 4, 3, NULL, 'thumbnails/ZhEIGW7p31JDWAoCHtReD2vtnJDYJ3eC3aJg8lFQ.png', 'pending', 1, NULL, '2025-04-19 08:14:50', '2025-04-23 12:13:15'),
(66, 'BV-190425-89083285', 'uố434324234234', 'uo434324234234', '<p>T&ocirc;i muốn <span style=\"background: #ffcccc; color: red; padding: 2px;\">H&ocirc;m nayuf l&agrave;</span></p>', NULL, 0, 4, 8, NULL, 'thumbnails/ZOv8oS83Wo3Xdigi2494iidwq3JoKqBqOl8SHFgH.png', 'rejected', 1, 1, '2025-04-19 08:25:04', '2025-04-25 01:56:48');
INSERT INTO `articles` (`article_id`, `code`, `title`, `slug`, `content`, `preview_content`, `contains_sensitive_content`, `author_id`, `category_id`, `subcategory_id`, `thumbnail_url`, `status`, `views`, `approved_by`, `created_at`, `updated_at`) VALUES
(67, 'BV-250425-29625747', 'dấdfsdfsdfsdfsdfsdfdấdfsdfsdfsdfsdfsdfdấdfsdfsdfsdfsdfsdf', 'dadfsdfsdfsdfsdfsdfdadfsdfsdfsdfsdfsdfdadfsdfsdfsdfsdfsdf', '<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Th&ocirc;ng tin được Tổng B&iacute; thư cho biết tại buổi gặp mặt hơn 300 c&aacute;n bộ l&atilde;o th&agrave;nh c&aacute;ch mạng, người c&oacute; c&ocirc;ng, gia đ&igrave;nh ch&iacute;nh s&aacute;ch ti&ecirc;u biểu miền Trung - T&acirc;y Nguy&ecirc;n, chiều 28/3 tại TP Đ&agrave; Nẵng, nh&acirc;n kỷ niệm 50 năm ng&agrave;y thống nhất đất nước (30/4/1975).</p>\r\n<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Theo người đứng đầu Đảng, dự kiến đầu th&aacute;ng 4 Trung ương họp v&agrave; t&iacute;nh to&aacute;n c&aacute;c phương &aacute;n sắp xếp tinh gọn bộ m&aacute;y. \"Dự kiến ban đầu cả nước c&ograve;n khoảng 34 tỉnh, th&agrave;nh phố tr&ecirc;n cơ sở sắp xếp lại 63 tỉnh, th&agrave;nh hiện nay; kết th&uacute;c hoạt động của đơn vị h&agrave;nh ch&iacute;nh cấp huyện; s&aacute;p nhập c&ograve;n khoảng 5.000 đơn vị h&agrave;nh ch&iacute;nh cấp x&atilde;, phường\", Tổng B&iacute; thư n&oacute;i.</p>\r\n<p class=\"Normal\" style=\"margin: 0px; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 1; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><img src=\"http://127.0.0.1:8000/storage/uploads/3ZzzWmHg2vKaZMqZbwKa1SDCyqlEt61TBD2vRDQ7.png\" width=\"361\" height=\"304\" data-moderated=\"true\" data-no-remoderation=\"true\" data-need-moderation=\"true\">d</p>\r\n<p class=\"Normal\" style=\"margin: 0px; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 1; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\"><img class=\"\" style=\"display: inline-block; vertical-align: middle;\" src=\"http://127.0.0.1:8000/storage/uploads/eI6JVnkHq1CbfrwF1TdMyVqFaEg19EPMw5uXXxvL.webp\" data-original-src=\"https://i1-vnexpress.vnecdn.net/2025/03/28/t3-1743175268-4625-1743175323.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=IVj4oqpa7djYAmI3VYHZ7g\" data-paste-id=\"img-paste-1745545397754-0\" data-need-moderation=\"true\" data-no-remoderation=\"true\" data-moderated=\"true\"></p>\r\n<p class=\"Normal\" style=\"margin: 0px; 