25-04-19 03:07:05'),
('BV-190425-37841245-v1', 65, 4, 'nước giao nhiệm vụ trướ', '<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Theo phương &aacute;n, Ủy ban Mặt trận Tổ quốc Việt Nam TP Đ&agrave; Nẵng v&agrave; Quảng Nam được hợp nhất, gồm 9 đầu mối. 48 tổ chức hội quần ch&uacute;ng do Đảng, Nh&agrave; nước giao nhiệm vụ trước mắt được giữ nguy&ecirc;n, sau đ&oacute; từng bước sắp xếp theo đề &aacute;n của Trung ương.</p>', 'nuoc-giao-nhiem-vu-truo', 3, NULL, 'thumbnails/ZhEIGW7p31JDWAoCHtReD2vtnJDYJ3eC3aJg8lFQ.png', '[\"ut_67fe0d8da8cff\"]', 'Tạo bài viết mới', '2025-04-19 08:14:50', '2025-04-19 08:14:50'),
('BV-190425-46077815-v1', 64, 4, 'hợp nhất, tương t', '<p><span style=\"color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; float: none; display: inline !important;\">iến thiết hai địa phương sẽ được hợp nhất, tương tự C&ocirc;ng ty TNHH MTV Khai th&aacute;c thủy lợi c</span></p>', 'hop-nhat-tuong-t', 3, NULL, 'thumbnails/segXjwOnMjf9k8WHUyjtxZN74vOeBOJVE3apXXp2.png', '[\"ut_67fe0d8da8cff\"]', 'Tạo bài viết mới', '2025-04-19 07:49:31', '2025-04-19 07:49:31'),
('BV-190425-78120815-v1', 55, 4, 'Phú Yên đề xuất hỗ trợ đi lại, chỗ ở cho 1.300 cán bộ sau sáp nhập tỉnh', '<p class=\"description\" style=\"margin: 0px 0px 15px; padding: 0px; box-sizing: border-box; text-rendering: optimizelegibility; font-size: 18px; line-height: 28.8px; font-weight: 400; color: #222222; font-family: arial; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Sở T&agrave;i ch&iacute;nh tỉnh đề xuất hỗ trợ chi ph&iacute; đi lại, chỗ ở cho 1.300 c&aacute;n bộ phải đi l&agrave;m tại tỉnh Đăk Lăk từ 1,6 đến tr&ecirc;n 3 triệu đồng mỗi th&aacute;ng</p>\r\n<article class=\"fck_detail \" style=\"margin: 0px; padding: 0px; box-sizing: border-box; text-rendering: optimizelegibility; width: 680px; float: left; position: relative; font: 400 18px / 28.8px arial; color: #222222; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">\r\n<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px;\">Theo Sở T&agrave;i ch&iacute;nh, dự kiến tổng số c&aacute;n bộ, c&ocirc;ng chức, vi&ecirc;n chức khi s&aacute;p nhập tỉnh c&oacute; nhu cầu đi từ TP Tuy H&ograve;a (Ph&uacute; Y&ecirc;n) đến TP Bu&ocirc;n Ma Thuột (Đăk Lăk) v&agrave; ngược lại l&agrave; khoảng 1.300 người (kh&ocirc;ng bao gồm c&aacute;c đơn vị lực lượng vũ trang).</p>\r\n<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px;\">Tuy nhi&ecirc;n, xe c&ocirc;ng vụ của tỉnh Ph&uacute; Y&ecirc;n kh&ocirc;ng đủ phục vụ số lượng tr&ecirc;n. Sở T&agrave;i ch&iacute;nh dự kiến chi ph&iacute; đi lại sau s&aacute;p nhập tỉnh l&agrave; 1,6 triệu đồng mỗi người/th&aacute;ng. Trường hợp kh&ocirc;ng sử dụng xe chung do tỉnh bố tr&iacute; th&igrave; hỗ trợ bằng tiền mặt.</p>\r\n<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px;\">Ngo&agrave;i ra, c&aacute;n bộ, c&ocirc;ng chức, vi&ecirc;n chức kh&ocirc;ng được bố tr&iacute; nh&agrave; ở c&ocirc;ng vụ sẽ được nhận chi ph&iacute; hỗ trợ chỗ ở l&agrave; 3 triệu đồng mỗi người/th&aacute;ng.</p>\r\n</article>', 'phu-yen-de-xuat-ho-tro-di-lai-cho-o-cho-1300-can-bo-sau-sap-nhap-tinh', 3, NULL, 'thumbnails/pebeyBUBvGNMkNAdhsoC7oT2EyLWhGRVXlcNpexT.png', '[\"rerum_67fe0d8da8d21\", \"est_67fe0d8da8d63\"]', 'Tạo bài viết mới', '2025-04-19 01:53:15', '2025-04-19 01:53:15'),
