INSERT INTO `article_versions` (`version_id`, `article_id`, `user_id`, `title`, `content`, `slug`, `category_id`, `subcategory_id`, `featured_image`, `tags`, `change_reason`, `created_at`, `updated_at`) VALUES
('BV-250425-83552576-v1', 69, 1, 'tỉnh giữ nguyên hiện trạng. Đó là Hà Nội, Huế, Lai C', '<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">tỉnh giữ nguy&ecirc;n hiện trạng. Đ&oacute; l&agrave; H&agrave; Nội, Huế, Lai Ch&acirc;u, Điện Bi&ecirc;n, Sơn La, Cao Bằng, Lạng Sơn, Quảng Ninh, Thanhtỉnh giữ nguy&ecirc;n hiện trạng. Đ&oacute; l&agrave; H&agrave; Nội, Huế, Lai Ch&acirc;u, Điện Bi&ecirc;n, Sơn La, Cao Bằng, Lạng Sơn, Quảng Ninh, Thanhtỉnh giữ nguy&ecirc;n hiện trạng. Đ&oacute; l&agrave; H&agrave; Nội, Huế, Lai Ch&acirc;u, Điện Bi&ecirc;n, Sơn La, Cao Bằng, Lạng Sơn, Quảng Ninh, ThanhC&aacute;c c&ocirc;ng việc n&agrave;y nhằm tổ chức lại kh&ocirc;ng gian ph&aacute;t triển kinh tế x&atilde; hội, th&uacute;c đẩy tăng trưởng, đảm bảo an ninh quốc ph&ograve;ng với tầm nh&igrave;n đến năm 2045-2050 v&agrave; xa hơn. Dự kiến, hệ thống tổ chức bộ m&aacute;y h&agrave;nh ch&iacute;nh sẽ được cơ cấu lại th&agrave;nh ba cấp: trung ương, tỉnh/th&agrave;nh phố v&agrave; x&atilde;/phường.</p>\r\n<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Việc s&aacute;p nhập cũng hướng đến mục ti&ecirc;u x&acirc;y dựng ch&iacute;nh quyền gần d&acirc;n, s&aacute;t d&acirc;n, phục vụ nh&acirc;n d&acirc;n tốt hơn, chủ động tiếp cận người d&acirc;n thay v&igrave; để người d&acirc;n phải t&igrave;m đến ch&iacute;nh quyền. Điều n&agrave;y tạo kh&ocirc;ng gian ph&aacute;t triển kinh tế x&atilde; hội cho từng khu vực, hướng tới sự phồn vinh của đất nước v&agrave; n&acirc;ng cao đời sống nh&acirc;n d&acirc;n.</p>\r\n<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Tổng B&iacute; thư cho biết hiện nay khoảng 80% quốc gia tr&ecirc;n thế giới tổ chức hệ thống ch&iacute;nh quyền ba cấp, trong khi Việt Nam l&agrave; một trong hơn 10% c&aacute;c nước duy tr&igrave; m&ocirc; h&igrave;nh bốn cấp. Thực tế cho thấy c&oacute; sự tr&ugrave;ng lặp trong chức năng, nhiệm vụ giữa c&aacute;c cấp h&agrave;nh ch&iacute;nh. Nhiều việc Trung ương l&agrave;m, tỉnh cũng thực hiện; tỉnh l&agrave;m, huyện v&agrave; x&atilde; cũng triển khai.</p>\r\n<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">\"Do vậy cần thiết phải sắp xếp lại theo hướng Trung ương l&agrave;m th&igrave; tỉnh th&ocirc;i, nếu tỉnh l&agrave;m th&igrave; x&atilde; th&ocirc;i v&agrave; nếu x&atilde; l&agrave;m th&igrave; tỉnh kh&ocirc;ng l&agrave;m nữa. Bộ m&aacute;y tinh gọn phải thống nhất như vậy\", Tổng B&iacute; thư n&oacute;i. Thay v&agrave;o đ&oacute;, Trung ương sẽ l&agrave;m c&ocirc;ng t&aacute;c chiến lược quốc gia, đối ngoại, quốc ph&ograve;ng, an ninh; c&ograve;n tỉnh phải triển khai những vấn đề cụ thể ở địa phương, đặc biệt l&agrave; cấp x&atilde;.</p>\r\n<figure class=\"tplCaption action_thumb_added\" style=\"margin: 0px auto 15px; padding: 0px; box-sizing: border-box; text-rendering: optimizelegibility; max-width: 100%; clear: both; position: relative; text-align: center; width: 680px; float: left; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\" itemprop=\"associatedMedia image\" itemscope=\"\" itemtype=\"http://schema.org/ImageObject\" data-size=\"true\">\r\n<div class=\"fig-picture el_valid\" style=\"margin: 0px; padding: 0px 0px 453.328px; box-sizing: border-box; text-rendering: optimizelegibility; width: 680px; float: left; display: table; -webkit-box-pack: center; justify-content: center; text-align: center; position: relative;\" data-src=\"https://i1-vnexpress.vnecdn.net/2025/03/28/z6451938940063-903b7bd05dfb5a0-6778-1413-1743169871.jpg?w=0&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=b410Ti7skYXl1kMud3azIQ\" data-sub-html=\"&lt;div class=&quot;ss-wrapper&quot;&gt;&lt;div class=&quot;ss-content&quot;&gt;\r\n&lt;p class=&quot;Image&quot;&gt;Tổng B&iacute; thư T&ocirc; L&acirc;m bắt tay thăm hỏi c&aacute;n bộ l&atilde;o th&agrave;nh miền Trung. Ảnh: &lt;em&gt;Nguyễn Đ&ocirc;ng&lt;/em&gt;&lt;/p&gt;\r\n&lt;/div&gt;&lt;/div&gt;\"><picture style=\"margin: 0px; padding: 0px; box-sizing: border-box; text-rendering: optimizelegibility;\"><source style=\"margin: 0px; padding: 0px; box-sizing: border-box; text-rendering: optimizelegibility;\" srcset=\"https://i1-vnexpress.vnecdn.net/2025/03/28/z6451938940063-903b7bd05dfb5a0-6778-1413-1743169871.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=jMhk_m1J4CSpDBKUxVzYJQ 1x, https://i1-vnexpress.vnecdn.net/2025/03/28/z6451938940063-903b7bd05dfb5a0-6778-1413-1743169871.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=uIq_1tWXIZnDEM8ck65d_g 1.5x, https://i1-vnexpress.vnecdn.net/2025/03/28/z6451938940063-903b7bd05dfb5a0-6778-1413-1743169871.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=SvoIz3w0EDLlJvYXojuRvw 2x\" data-srcset=\"https://i1-vnexpress.vnecdn.net/2025/03/28/z6451938940063-903b7bd05dfb5a0-6778-1413-1743169871.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=jMhk_m1J4CSpDBKUxVzYJQ 1x, https://i1-vnexpress.vnecdn.net/2025/03/28/z6451938940063-903b7bd05dfb5a0-6778-1413-1743169871.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=uIq_1tWXIZnDEM8ck65d_g 1.5x, https://i1-vnexpress.vnecdn.net/2025/03/28/z6451938940063-903b7bd05dfb5a0-6778-1413-1743169871.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=SvoIz3w0EDLlJvYXojuRvw 2x\"></picture>\r\n<p style=\"margin: 0px; padding: 0px; line-height: 1;\"><img class=\"\" style=\"display: inline-block; vertical-align: middle;\" src=\"http://127.0.0.1:8000/storage/uploads/VhxvOo79LWUcjVBQpJKs7WaPRp8INxEPDkhstQwH.webp\" data-original-src=\"https://i1-vnexpress.vnecdn.net/2025/03/28/z6451938940063-903b7bd05dfb5a0-6778-1413-1743169871.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=jMhk_m1J4CSpDBKUxVzYJQ\" data-paste-id=\"img-paste-1745546668233-0\" data-need-moderation=\"true\" data-moderated=\"true\" data-no-remoderation=\"true\"></p>\r\n</div>\r\n<figcaption style=\"margin: 0px; padding: 0px; box-sizing: border-box; text-rendering: optimizelegibility; width: 680px; float: left; text-align: left;\" itemprop=\"description\">\r\n<p class=\"Image\" style=\"margin: 0px; padding: 10px 0px 0px; box-sizing: border-box; text-rendering: optimizespeed; font: 400 14px / 22.4px arial; text-align: left; color: #222222;\">Tổng B&iacute; thư T&ocirc; L&acirc;m bắt tay thăm hỏi c&aacute;n bộ l&atilde;o th&agrave;nh miền Trung. Ảnh:&nbsp;<em style=\"margin: 0px; padding: 0px; box-sizing: border-box; text-rendering: optimizelegibility;\">Nguyễn Đ&ocirc;ng</em></p>\r\n</figcaption>\r\n</figure>\r\n<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Tổng B&iacute; thư nhấn mạnh vai tr&ograve; quan trọng nhất l&agrave; ch&iacute;nh quyền cấp x&atilde;, bởi đ&acirc;y l&agrave; cấp cơ sở, trực tiếp tổ chức triển khai mọi chủ trương, nghị quyết của Đảng v&agrave; Nh&agrave; nước. Nếu c&aacute;c nghị quyết kh&ocirc;ng được thực hiện đến chi bộ, đảng vi&ecirc;n v&agrave; nh&acirc;n d&acirc;n th&igrave; chỉ mang t&iacute;nh h&igrave;nh thức.</p>\r\n<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">&Ocirc;ng cho biết ch&iacute;nh quyền cấp x&atilde; trước đ&acirc;y chưa được ph&acirc;n cấp, phtỉnh giữ nguy&ecirc;n hiện trạng. Đ&oacute; l&agrave; H&agrave; Nội, Huế, Lai Ch&acirc;u, Điện Bi&ecirc;n, Sơn La, Cao Bằng, Lạng Sơn, Quảng Ninh, Thanh&acirc;n quyền đầy đủ, &iacute;t tr&aacute;ch nhiệm về c&aacute;c vấn đề kinh tế x&atilde; hội; y tế, gi&aacute;o dục do c&aacute;c cấp tỉnh, huyện đảm nhiệm; x&atilde; chủ yếu giải quyết thủ tục h&agrave;nh ch&iacute;nh. Nay quy tr&igrave;nh sẽ đảo ngược. \"C&aacute;n bộ x&atilde;, c&aacute;n bộ cơ sở phải thực sự nắm bắt t&acirc;m tư, nguyện vọng của nh&acirc;n d&acirc;n, hiểu r&otilde; những mong muốn, kh&oacute; khăn v&agrave; nhu cầu của người d&acirc;n để chủ động giải quyết\", Tổng B&iacute; thư n&oacute;i.</p>\r\n<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Theo dự thảo Nghị quyết của Ủy ban Thường vụ Quốc hội do Bộ Nội vụ chủ tr&igrave; soạn thảo, cả nước c&oacute; 11 đơn vị h&agrave;nh ch&iacute;nh cấp tỉnh giữ nguy&ecirc;n hiện trạng. Đ&oacute; l&agrave; H&agrave; Nội, Huế, Lai Ch&acirc;u, Điện Bi&ecirc;n, Sơn La, Cao Bằng, Lạng Sơn, Quảng Ninh, Thanh H&oacute;a, Nghệ An v&agrave; H&agrave; Tĩnh. 52 địa phương c&ograve;n lại thuộc diện phải sắp xếp, bao gồm cả 4 th&agrave;nh phố trực thuộc Trung ương l&agrave; TP HCM, Hải Ph&ograve;ng, Đ&agrave; Nẵng, Cần Thơ.</p>\r\n<div class=\"box_brief_info\" style=\"margin: 0px 0px 15px; padding: 10px 15px 0px; box-sizing: border-box; text-rendering: optimizelegibility; width: 680px; float: left; border-top: 1px solid rgb(204, 204, 204); color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">\r\n<p class=\"Normal smart-ptt1-p\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px;\">Tại cuộc gặp, Tổng B&iacute; thư cũng cho biết t&igrave;nh trạng l&atilde;ng ph&iacute; hiện nay \"rất đ&aacute;ng b&aacute;o động\" v&agrave; tr&ecirc;n một kh&iacute;a cạnh \"c&ograve;n g&acirc;y tổn thất cao hơn cả tham nhũng, ti&ecirc;u cực\". Theo b&aacute;o c&aacute;o của Bộ C&ocirc;ng an, đến th&aacute;ng 4/2024, cả nước c&ograve;n tồn đọng khoảng 2.800 c&ocirc;ng tr&igrave;nh, dự &aacute;n chậm tiến độ hoặc kh&ocirc;ng đưa được v&agrave;o sử dụng, c&oacute; nguy cơ l&atilde;ng ph&iacute;. Khoảng 483 dự &aacute;n với diện t&iacute;ch gần 20.000 ha chưa được khai th&aacute;c. Thống k&ecirc; sơ bộ từ c&aacute;c tỉnh cũng cho thấy 3.495 dự &aacute;n chậm tiến độ, chiếm tổng diện t&iacute;ch gần 55.000 ha.</p>\r\n<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px;\">\"C&oacute; những dự &aacute;n chậm h&agrave;ng chục năm l&agrave; điều kh&ocirc;ng thể chấp nhận được, nhất l&agrave; khi nguồn lực đất đai của ch&uacute;ng ta vốn đ&atilde; kh&oacute; khăn. Vừa qua H&agrave; Nội b&aacute;o c&aacute;o mới r&agrave; so&aacute;t, thu hồi hai trong số h&agrave;ng trăm dự &aacute;n đ&atilde; thu về tr&ecirc;n 8.000 tỷ đồng. Nếu ch&uacute;ng ta xử l&yacute; tốt vấn đề n&agrave;y, nguồn lực để ph&aacute;t triển đất nước sẽ rất lớn\", Tổng B&iacute; thư nhấn mạnh.</p>\r\n</div>', 'tinh-giu-nguyen-hien-trang-do-la-ha-noi-hue-lai-c', 3, NULL, 'thumbnails/2nUHOFDQ9Xqs7G4hG68QCS3BorOzv5eKuTsH34Hn.png', '[\"ut_67fe0d8da8cff\", \"magnam_67fe0d8da8d41\"]', 'Tạo bài viết mới', '2025-04-25 02:05:22', '2025-04-25 02:05:22'),
('BV-250425-86322308-v1', 68, 1, 'fvsdfsdfsdfsdfsdfsdfdsfsdfsdfsdfsdfsdfsdfsdfdsfsdfsdfsd', '<p>&nbsp;</p>\r\n<p>đai của ch&uacute;ng ta vốn đ&atilde; kh&oacute; khăn. Vừa qua H&agrave; Nội b&aacute;o c&aacute;o mới r&agrave; so&aacute;t, thu hồi hai trong số h&agrave;ng trăm dự &aacute;n đ&atilde; thu về tr&ecirc;n 8.000 tỷ đồng. Nếu ch&uacute;ng ta xử l&yacute; tốt vấn đề n</p>\r\n<p>đai của ch&uacute;ng ta vốn đ&atilde; kh&oacute; khăn. Vừa qua H&agrave; Nội b&aacute;o c&aacute;o mới r&agrave; so&aacute;t, thu hồi hai trong số h&agrave;ng trăm dự &aacute;n đ&atilde; thu về tr&ecirc;n 8.000 tỷ đồng. Nếu ch&uacute;ng ta xử l&yacute; tốt vấn đề n</p>\r\n<p>đai của ch&uacute;ng ta vốn đ&atilde; kh&oacute; khăn. Vừa qua H&agrave; Nội b&aacute;o c&aacute;o mới r&agrave; so&aacute;t, thu hồi hai trong số h&agrave;ng trăm dự &aacute;n đ&atilde; thu về tr&ecirc;n 8.000 tỷ đồng. Nếu ch&uacute;ng ta xử l&yacute; tốt vấn đề n</p>\r\n<p>đai của ch&uacute;ng ta vốn đ&atilde; kh&oacute; khăn. Vừa qua H&agrave; Nội b&aacute;o c&aacute;o mới r&agrave; so&aacute;t, thu hồi hai trong số h&agrave;ng trăm dự &aacute;n đ&atilde; thu về tr&ecirc;n 8.000 tỷ đồng. Nếu ch&uacute;ng ta xử l&yacute; tốt vấn đề nccccccc</p>\r\n<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">&nbsp;B&iacute; thư cho biết hiện nay khoảng 80% quốc gia tr&ecirc;n thế giới tổ chức hệ thống ch&iacute;nh quyền ba cấp, trong khi Việt Nam l&agrave; một trong hơn 10% c&aacute;c nước duy tr&igrave; m&ocirc; h&igrave;nh bốn cấp. Thực tế cho thấy c&oacute; sự tr&ugrave;ng lặp trong chức năng, nhiệm vụ giữa c&aacute;c cấp h&agrave;nh ch&iacute;nh. Nhiều việc Trung ương l&agrave;m, tỉnh cũng thực hiện; tỉnh l&agrave;m, huyện v&agrave; x&atilde; cũng triển khai.</p>\r\n<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">\"Do vậy cần thiết phải sắp xếp lại theo hướng Trung ương l&agrave;m th&igrave; tỉnh th&ocirc;i, nếu tỉnh l&agrave;m th&igrave; x&atilde; th&ocirc;i v&agrave; nếu x&atilde; l&agrave;m th&igrave; tỉnh kh&ocirc;ng l&agrave;m nữa. Bộ m&aacute;y tinh gọn phải thống nhất như vậy\", Tổng B&iacute; thư n&oacute;i. Thay v&agrave;o đ&oacute;, Trung ương sẽ l&agrave;m c&ocirc;ng t&aacute;c chiến lược quốc gia, đối ngoại, quốc ph&ograve;ng, an ninh; c&ograve;n tỉnh phải triển khai những vấn đề cụ thể ở địa phương, đặc biệt l&agrave; cấp x&atilde;.</p>\r\n<figure class=\"tplCaption action_thumb_added\" style=\"margin: 0px auto 15px; padding: 0px; box-sizing: border-box; text-rendering: optimizelegibility; max-width: 100%; clear: both; position: relative; text-align: center; width: 680px; float: left; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\" itemprop=\"associatedMedia image\" itemscope=\"\" itemtype=\"http://schema.org/ImageObject\" data-size=\"true\">\r\n<div class=\"fig-picture el_valid\" style=\"margin: 0px; padding: 0px 0px 453.328px; box-sizing: border-box; text-rendering: optimizelegibility; width: 680px; float: left; display: table; -webkit-box-pack: center; justify-content: center; text-align: center; position: relative;\" data-src=\"https://i1-vnexpress.vnecdn.net/2025/03/28/z6451938940063-903b7bd05dfb5a0-6778-1413-1743169871.jpg?w=0&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=b410Ti7skYXl1kMud3azIQ\" data-sub-html=\"&lt;div class=&quot;ss-wrapper&quot;&gt;&lt;div class=&quot;ss-content&quot;&gt;\r\n&lt;p class=&quot;Image&quot;&gt;Tổng B&iacute; thư T&ocirc; L&acirc;m bắt tay thăm hỏi c&aacute;n bộ l&atilde;o th&agrave;nh miền Trung. Ảnh: &lt;em&gt;Nguyễn Đ&ocirc;ng&lt;/em&gt;&lt;/p&gt;\r\n&lt;/div&gt;&lt;/div&gt;\"><picture style=\"margin: 0px; padding: 0px; box-sizing: border-box; text-rendering: optimizelegibility;\"><source style=\"margin: 0px; padding: 0px; box-sizing: border-box; text-rendering: optimizelegibility;\" srcset=\"https://i1-vnexpress.vnecdn.net/2025/03/28/z6451938940063-903b7bd05dfb5a0-6778-1413-1743169871.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=jMhk_m1J4CSpDBKUxVzYJQ 1x, https://i1-vnexpress.vnecdn.net/2025/03/28/z6451938940063-903b7bd05dfb5a0-6778-1413-1743169871.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=uIq_1tWXIZnDEM8ck65d_g 1.5x, https://i1-vnexpress.vnecdn.net/2025/03/28/z6451938940063-903b7bd05dfb5a0-6778-1413-1743169871.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=SvoIz3w0EDLlJvYXojuRvw 2x\" data-srcset=\"https://i1-vnexpress.vnecdn.net/2025/03/28/z6451938940063-903b7bd05dfb5a0-6778-1413-1743169871.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=jMhk_m1J4CSpDBKUxVzYJQ 1x, https://i1-vnexpress.vnecdn.net/2025/03/28/z6451938940063-903b7bd05dfb5a0-6778-1413-1743169871.jpg?w=1020&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=uIq_1tWXIZnDEM8ck65d_g 1.5x, https://i1-vnexpress.vnecdn.net/2025/03/28/z6451938940063-903b7bd05dfb5a0-6778-1413-1743169871.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=2&amp;fit=crop&amp;s=SvoIz3w0EDLlJvYXojuRvw 2x\"></picture>\r\n<p style=\"margin: 0px; padding: 0px; line-height: 1;\"><img class=\"\" style=\"display: inline-block; vertical-align: middle;\" src=\"http://127.0.0.1:8000/storage/uploads/xknRDo8i2wtRp82aOJ3bRXgLgunms84Bz5rmdu0Q.webp\" data-original-src=\"https://i1-vnexpress.vnecdn.net/2025/03/28/z6451938940063-903b7bd05dfb5a0-6778-1413-1743169871.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=jMhk_m1J4CSpDBKUxVzYJQ\" data-paste-id=\"img-paste-1745545833101-0\" data-need-moderation=\"true\" data-moderated=\"true\" data-no-remoderation=\"true\"></p>\r\n</div>\r\n<figcaption style=\"margin: 0px; padding: 0px; box-sizing: border-box; text-rendering: optimizelegibility; width: 680px; float: left; text-align: left;\" itemprop=\"description\">\r\n<p class=\"Image\" style=\"margin: 0px; padding: 10px 0px 0px; box-sizing: border-box; text-rendering: optimizespeed; font: 400 14px / 22.4px arial; text-align: left; color: #222222;\">Tổng B&iacute; thư T&ocirc; L&acirc;m bắt tay thăm hỏi c&aacute;n bộ l&atilde;o th&agrave;nh miền Trung. Ảnh:&nbsp;<em style=\"margin: 0px; padding: 0px; box-sizing: border-box; text-rendering: optimizelegibility;\">Nguyễn Đ&ocirc;ng</em></p>\r\n</figcaption>\r\n</figure>\r\n<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Tổng B&iacute; thư nhấn mạnh vai tr&ograve; quan trọng nhất l&agrave; ch&iacute;nh quyền cấp x&atilde;, bởi đ&acirc;y l&agrave; cấp cơ sở, trực tiếp tổ chức triển khai mọi chủ trương, nghị quyết của Đảng v&agrave; Nh&agrave; nước. Nếu c&aacute;c nghị quyết kh&ocirc;ng được thực hiện đến chi bộ, đảng vi&ecirc;n v&agrave; nh&acirc;n d&acirc;n th&igrave; chỉ mang t&iacute;nh h&igrave;nh thức.</p>\r\n<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">&Ocirc;ng cho biết ch&iacute;nh quyền cấp x&atilde; trước đ&acirc;y chưa được ph&acirc;n cấp, ph&acirc;n quyền đầy đủ, &iacute;t tr&aacute;ch nhiệm về c&aacute;c vấn đề kinh tế x&atilde; hội; y tế, gi&aacute;o dục do c&aacute;c cấp tỉnh, huyện đảm nhiệm; x&atilde; chủ yếu giải quyết thủ tục h&agrave;nh ch&iacute;nh. Nay quy tr&igrave;nh sẽ đảo ngược. \"C&aacute;n bộ x&atilde;, c&aacute;n bộ cơ sở phải thực sự nắm bắt t&acirc;m tư, nguyện vọng của nh&acirc;n d&acirc;n, hiểu r&otilde; những mong muốn, kh&oacute; khăn v&agrave; nhu cầu của người d&acirc;n để chủ động giải quyết\", Tổng B&iacute; thư n&oacute;i.</p>\r\n<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px; color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">Theo dự thảo Nghị quyết của Ủy ban Thường vụ Quốc hội do Bộ Nội vụ chủ tr&igrave; soạn thảo, cả nước c&oacute; 11 đơn vị h&agrave;nh ch&iacute;nh cấp tỉnh giữ nguy&ecirc;n hiện trạng. Đ&oacute; l&agrave; H&agrave; Nội, Huế, Lai Ch&acirc;u, Điện Bi&ecirc;n, Sơn La, Cao Bằng, Lạng Sơn, Quảng Ninh, Thanh H&oacute;a, Nghệ An v&agrave; H&agrave; Tĩnh. 52 địa phương c&ograve;n lại thuộc diện phải sắp xếp, bao gồm cả 4 th&agrave;nh phố trực thuộc Trung ương l&agrave; TP HCM, Hải Ph&ograve;ng, Đ&agrave; Nẵng, Cần Thơ.</p>\r\n<div class=\"box_brief_info\" style=\"margin: 0px 0px 15px; padding: 10px 15px 0px; box-sizing: border-box; text-rendering: optimizelegibility; width: 680px; float: left; border-top: 1px solid rgb(204, 204, 204); color: #222222; font-family: arial; font-size: 18px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;\">\r\n<p class=\"Normal smart-ptt1-p\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px;\">Tại cuộc gặp, Tổng B&iacute; thư cũng cho biết t&igrave;nh trạng l&atilde;ng ph&iacute; hiện nay \"rất đ&aacute;ng b&aacute;o động\" v&agrave; tr&ecirc;n một kh&iacute;a cạnh \"c&ograve;n g&acirc;y tổn thất cao hơn cả tham nhũng, ti&ecirc;u cực\". Theo b&aacute;o c&aacute;o của Bộ C&ocirc;ng an, đến th&aacute;ng 4/2024, cả nước c&ograve;n tồn đọng khoảng 2.800 c&ocirc;ng tr&igrave;nh, dự &aacute;n chậm tiến độ hoặc kh&ocirc;ng đưa được v&agrave;o sử dụng, c&oacute; nguy cơ l&atilde;ng ph&iacute;. Khoảng 483 dự &aacute;n với diện t&iacute;ch gần 20.000 ha chưa được khai th&aacute;c. Thống k&ecirc; sơ bộ từ c&aacute;c tỉnh cũng cho thấy 3.495 dự &aacute;n chậm tiến độ, chiếm tổng diện t&iacute;ch gần 55.000 ha.</p>\r\n<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px;\">\"C&oacute; những dự &aacute;n chậm h&agrave;ng chục năm l&agrave; điều kh&ocirc;ng thể chấp nhận được, nhất l&agrave; khi nguồn lực đất đai của ch&uacute;ng ta vốn đ&atilde; kh&oacute; khăn. Vừa qua H&agrave; Nội b&aacute;o c&aacute;o mới r&agrave; so&aacute;t, thu hồi hai trong số h&agrave;ng trăm dự &aacute;n đ&atilde; thu về tr&ecirc;n 8.000 tỷ đồng. Nếu ch&uacute;ng ta xử l&yacute; tốt vấn đề n&agrave;y, nguồn lực để ph&aacute;t triển đất nước sẽ rất lớn\", Tổng B&iacute; thư nhấn mạnh.ccccccccccccccccc</p>\r\n<p class=\"Normal\" style=\"margin: 0px 0px 1em; padding: 0px; box-sizing: border-box; text-rendering: optimizespeed; line-height: 28.8px;\">đai của ch&uacute;ng ta vốn đ&atilde; kh&oacute; khăn. Vừa qua H&agrave; Nội b&aacute;o c&aacute;o mới r&agrave; so&aacute;t, thu hồi hai trong số h&agrave;ng trăm dự &aacute;n đ&atilde; thu về tr&ecirc;n 8.000 tỷ đồng. Nếu ch&uacute;ng ta xử l&yacute; tốt vấn đề n</p>\r\n</div>', 'fvsdfsdfsdfsdfsdfsdfdsfsdfsdfsdfsdfsdfsdfsdfdsfsdfsdfsd', 3, NULL, 'thumbnails/UH8lFgeVysXLEvxu6ZvQZJnnd95krMc542pb9wWX.png', '[\"ut_67fe0d8da8cff\", \"est_67fe0d8da8d63\"]', 'Tạo bài viết mới', '2025-04-25 01:51:31', '2025-04-25 01:51:31');
